 const buckling=entries.find(item=>item.key==='buckling');
 buckling.sectionIndex=true;
 buckling.sections.push(
  ['剛性のつり合いから座屈荷重を求める',[
   '① 弾性剛性Kを組み立て、基準荷重ベクトルf₀の静解析 K u₀ = f₀ を解きます。u₀から各要素の軸力・応力を求め、それが微小な追加変形に及ぼす剛性を基準荷重での差分剛性 Kɢ₀ として組み立てます。引張軸力Nを正とすると、梁の横変位wに対する幾何剛性のエネルギー項は ½∫N(w′)² dx です。圧縮ならNが負なので、この項が横曲げの安定性を下げます。',
   '② 荷重が λ f₀ に比例し、内力分布も保たれるなら差分剛性は λKɢ₀ です。微小な座屈変形φに対する二次のポテンシャルは ½ φᵀKφ + ½λ φᵀKɢ₀φ。1項目は弾性変形によるエネルギー、2項目は基準応力状態の寄与です。',
   '③ 対称な剛性行列でφの各成分について微分すると、(K + λKɢ₀)φ = 0 を得ます。φ = 0 は常に成立します。φ ≠ 0 の変形が可能になるには det(K + λKɢ₀) = 0、つまり接線剛性が特異になる必要があります。これが一般化固有値問題 Kφ = −λKɢ₀φ です。',
   '④ 各固有値λᵢをf₀に掛けると対応する座屈荷重が得られます。圧縮向きのf₀に正のλを掛けても向きは圧縮のままです。φの長さや符号は任意なので、モードの変形図を実変位として読みません。',
   '同じ荷重パターンを最初から10倍にして計算する場合、通常の比例載荷では座屈係数は1/10になり、座屈荷重は同じです。基準1000 Nで係数2.4、基準2000 Nで1.2なら、どちらも臨界荷重は2400 Nです。力・温度差・強制伸びを含む場合は、何を比例して増やすモデルかを明示します。'
  ]],
  ['INV・SINV・Lanczosの使い分け',[
   'SOL 105に使えるのは逆反復INV、改良逆反復SINV、Lanczosです。INVは探索条件によってモードを取りこぼすため、ガイドは通常の選択として勧めていません。SINVはSturm列による固有値の個数確認を使い、範囲が分かっていて必要根が少ない場合などに比較できます。',
   '通常はLanczosを起点にし、モデル自由度数、必要な根の数、利用可能なメモリ、予想する固有値範囲で選びます。EIGRLではV1/V2が倍率の上下限、NDが必要根数です。EIGBではL1/L2で範囲を指定し、NEPによる正の根数の見積りはINVで用います。'
  ]],
  ['局所的に差分剛性を除くとき',[
   'MSCのSOL 105では座屈SUBCASEのPARAM,EXCLUDEとBulk DataのSET1で制御できます。正の値nはSET1で選んだ節点の差分剛性を除き、負の値−nはその節点側の差分剛性を残します。0はこの選択による除外を行わない設定です。',
   '除外の境界は、調べたい箇所から離れた剛性の高い領域や自然なメッシュ境界に置きます。除外なしの結果とも比較します。別の領域の座屈モードを見やすくする操作なので、構造全体の最低座屈荷重を報告する場合は除外条件を明示します。'
  ]],
  ['適用限界とメッシュの確認',[
   '基準となる変形が小さく、材料が弾性で、外荷重の向きと内力分布を比例載荷で扱えることを前提にします。追従荷重、接触状態の変化、材料降伏、大きな変形、初期不整に敏感な薄肉構造では、非線形解析や試験との照合を検討します。',
   '差分剛性に対応する要素かを確認します。ガイドはCTUBE・CROD系、CBAR・CBEAM系、三角形・四角形シェル、CSHEAR、CHEXA・CPENTA・CTETRAを挙げています。座屈波形は半波当たり少なくとも5節点を初期目安にし、目的のモードと係数の収束を見ます。三次元シェルのCQUAD4・CTRIA3ではK6ROTも結果に関係し得ます。'
  ]]
 );
 buckling.sources=[src(499,'第13章 PDF 499–534'),src(500,'有限要素の式とSOL 105 PDF 500–505'),src(505,'固有値抽出と入力欄 PDF 505–508'),src(508,'差分剛性の局所除外 PDF 508–509'),src(510,'例題1 · オイラー柱'),src(515,'例題2 · 横座屈'),src(520,'例題3 · 平面骨組み'),src(523,'例題4 · 補強パネル'),src(527,'例題5 · 円筒'),src(532,'例題6 · 複数座屈ケース')];

